 "new_string": "from decimal import Decimal

from src.billing.tax import line_total, tax_for


def test_line_total():
    assert line_total([{"quantity": 2, "unit_cents": 150}]) == 300


def test_tax_for_basic():
    assert tax_for(10000, Decimal("0.0825")) == 825
    assert tax_for(10000, "0.0825") == 825
    assert tax_for(10000, 0.0825) == 825
    assert tax_for(0, Decimal("0.1")) == 0


def test_tax_for_rounds_half_even():
    assert tax_for(25, Decimal("0.1")) == 2  # 2.5 -> 2
    assert tax_for(35, Decimal("0.1")) == 4  # 3.5 -> 4
    assert tax_for(26, Decimal("0.1")) == 3  # 2.6 -> 3"
}

